function PVPArenaMainPanelNode:__init()
    self.pvpArenaDojo      = pvpArenaComponent:GetPVPArenaDojo()
    self.pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()

    --- 是否是观众
    self.isAudience   = checkNumber(self.pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience

end

function PVPArenaMainPanelNode:__delete()
    self.pvpArenaDojo = nil
    self.pvpArenaEntryDojo = nil
    self:UnRegisterCountdownEvent()
    self = nil
end

function PVPArenaMainPanelNode:Awake()
    --- 对阵图
    UIEventProxy.Create(self.FontStyleButton.gameObject).onPointerClick = Bind(self, self.OnClickEnterMatchChartAction)
    --- 编队
    UIEventProxy.Create(self.FontStyleButton1.gameObject).onPointerClick = Bind(self, self.OnClickEditTeamAction)
    --- 对阵图
    UIEventProxy.Create(self.FontStyleButton2.gameObject).onPointerClick = Bind(self, self.OnClickEnterMatchChartAction)

    UIEventProxy.Create(self.CheckLoopListView.gameObject).onPointerClick = Bind(self, self.OnClickEnterMatchChartAction)

    self.FontStyleButtonText1.text = localize("编队")
end

function PVPArenaMainPanelNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

function PVPArenaMainPanelNode:InitMatchChart()
    local matchChart    = {}
    local wheelScope    = pvpArenaComponent:GetAllWheelScope()
    local pvpArenaDojo  = self.pvpArenaDojo
    local map           = checkTable(pvpArenaDojo.map)
    local matcherInfo   = checkTable(pvpArenaDojo.matcherInfo)
    local isInBattle    = checkNumber(self.pvpArenaEntryDojo.battleStatus) == Constants.PVPArenaBattleStatus.InBattle
    local curWheel      = pvpArenaComponent:GetCurWheel()
    local scope         = wheelScope[curWheel]
    local positionWheel = 1
    local startWheelScope = wheelScope[positionWheel]
    local _, startRightBoundary = SafeUnpack(startWheelScope)
    ---获取当前轮的右边界
    local _, rightBoundary = SafeUnpack(scope)

    for position = 1, rightBoundary, 2 do
        local oneMatchChartData = PVPArenaUtils.CreateOneMatchChartData(position, positionWheel, isInBattle, map, matcherInfo)
        ---  and (checkNumber(oneMatchChartData.leftScore) > 0 or checkNumber(oneMatchChartData.rightScore) > 0 or oneMatchChartData.inBattle)
        if oneMatchChartData then
            table.insert(matchChart, oneMatchChartData)
        end

        if position == startRightBoundary then
            positionWheel = positionWheel + 1
            startWheelScope = wheelScope[positionWheel]
            if not startWheelScope then
                local _, newRightNum = SafeUnpack(startWheelScope)
                startRightBoundary = newRightNum
            end
        end
    end
    self:SetMatchChart(matchChart)
    return matchChart
end

function PVPArenaMainPanelNode:InitCommonUIData(isAudience)
    ---@type Constants.PVPArenaMainPanelStatus
    local mainPanelStatus = pvpArenaComponent:GetMainPanelStatus()

    local titleText, titleImgName
    local countdownTitleText, countdownTitleColor
    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    if seasonFlag == PVPArenaMainPanelStatus.Closed then
        titleText = localize("休赛期")
        titleImgName = "pvp_img_title_group_green"
        countdownTitleText = localize("距离比赛开始")
        countdownTitleColor = XLuaUtils.HexToColor(Green)

    elseif seasonFlag == PVPArenaSeasonFullStatus.Quiz then
        titleText = isAudience and localize("竞猜期") or localize("备战期")
        titleImgName = "pvp_img_title_group_green"
        countdownTitleText = isAudience and localize("距离推选结束") or localize("距离比赛开始")
        countdownTitleColor = XLuaUtils.HexToColor(Green)

    elseif seasonFlag == PVPArenaSeasonFullStatus.Notice then
        titleText = isAudience and localize("公示期") or localize("备战期")
        titleImgName = isAudience and "pvp_img_title_group_blue" or "pvp_img_title_group_green"
        countdownTitleText = localize("距离比赛开始")
        countdownTitleColor = XLuaUtils.HexToColor(isAudience and Blue or Green)

    else
        --- 是否是观赛状态
        local isWatch = isAudience or mainPanelStatus == PVPArenaMainPanelStatus.WatchTheMatch
        local isInMatch = mainPanelStatus == PVPArenaMainPanelStatus.InMatch
        if seasonFlag == PVPArenaSeasonFullStatus.Group then
            titleText = localize("小组赛")
            titleImgName = isAudience and "pvp_img_title_group_red" or "pvp_img_title_group_red"

            countdownTitleText = isWatch and
                    localize("距离小组赛结束") or
                    localize("预计下轮开始时间")

            countdownTitleColor = XLuaUtils.HexToColor((isWatch or not isInMatch) and Red or White)

        elseif seasonFlag == PVPArenaSeasonFullStatus.OffSeason then
            titleText = localize("休赛期")
            titleImgName = "pvp_img_title_group_green"
            countdownTitleText = isWatch and localize("距离休赛期结束") or localize("距离比赛开始")
            countdownTitleColor = XLuaUtils.HexToColor(Green)

        elseif seasonFlag == PVPArenaSeasonFullStatus.Final then
            titleText = localize("最终赛")
            titleImgName = isWatch and "pvp_img_title_group_red" or "pvp_img_title_group_red"

            countdownTitleText = (isWatch or pvpArenaComponent:GetCurWheel() == pvpArenaComponent:GetMatchChartTotalWheelNum()) and
                    localize("距离最终赛结束") or
                    localize("预计下轮开始时间")
            countdownTitleColor = XLuaUtils.HexToColor((isWatch or not isInMatch) and Red or White)
        end
    end

    return titleText, titleImgName, countdownTitleText, countdownTitleColor
end

function PVPArenaMainPanelNode:RegisterCountdownEvent()
    if self.__EventCountdownUpdate then return end
    self.__EventCountdownUpdate = Events.AddListener(Constants.EventNames.PVPArenaCountDownUpdate, Bind(self, self.OnEventCountdownUpdate))
end
function PVPArenaMainPanelNode:UnRegisterCountdownEvent()
    if self.__EventCountdownUpdate then
        Events.RemoveListener(Constants.EventNames.PVPArenaCountDownUpdate, self.__EventCountdownUpdate)
        self.__EventCountdownUpdate = nil
    end
end

