function PVPArenaMainPanelNode:RefreshUI()

    ---@type Constants.PVPArenaMainPanelStatus
    local mainPanelStatus = pvpArenaComponent:GetMainPanelStatus()
    --------------------------------------------
    --- 投票相关
    local isShowQuizInfo = checkBool(QuizInfoShowType[mainPanelStatus])
    KTool.SetActive(self.FontStyleButton.gameObject, isShowQuizInfo)
    KTool.SetActive(self.PlayerGroup.gameObject,     isShowQuizInfo)

    if isShowQuizInfo then
        self:RefreshQuizInfo()

        local isNoComplete = mainPanelStatus == PVPArenaMainPanelStatus.NoQuiz or
                mainPanelStatus == PVPArenaMainPanelStatus.NoQuizComplete
        self.FontStyleButtonText.text = isNoComplete and localize("推选") or localize("查看")
    end

    --------------------------------------------
    --- 对手相关
    local isShowRivalInfo = checkBool(RivalInfoShowType[mainPanelStatus])
    KTool.SetActive(self.RivalGroup.gameObject, isShowRivalInfo)
    KTool.SetActive(self.twoGroup.gameObject, isShowRivalInfo)
    if isShowRivalInfo then
        KTool.SetActive(self.FontStyleButton1.gameObject, PVPArenaMainPanelStatus.InBattle ~= mainPanelStatus and PVPArenaMainPanelStatus.Closed ~= mainPanelStatus)
        self:RefreshRivalInfo()
    end

    --------------------------------------------
    --- 观赛相关
    local isShowMatchList = mainPanelStatus == PVPArenaMainPanelStatus.WatchTheMatch
    KTool.SetActive(self.CheckLoopListView.gameObject, isShowMatchList)
    KTool.SetActive(self.TvRole.gameObject,          not isShowMatchList)
    if isShowMatchList then
        self:RefreshMatchList()
    end

    --------------------------------------------
    --- 通用
    self:RefreshCommonUI(mainPanelStatus)
end

function PVPArenaMainPanelNode:RefreshQuizInfo()
    ---@type PVPArenaQuizPlayerGroupNode
    local mbEnv = CfUtils.GetLuaScr(self.PlayerGroup.gameObject, PVPArenaQuizPlayerGroupNodePath)
    if mbEnv == nil then return end

    mbEnv:RefreshUI()
end

function PVPArenaMainPanelNode:RefreshRivalInfo()
    ---@type PVPArenaRivalGroupNode
    local mbEnv = CfUtils.GetLuaScr(self.RivalGroup.gameObject, PVPArenaRivalGroupNodePath)
    if mbEnv == nil then return end

    mbEnv:RefreshUI()
end

