---RefreshMatchList
---刷新匹配列表
function PVPArenaMainPanelNode:RefreshMatchList()
    local matchChart = self:InitMatchChart()
    local count = table.count(matchChart)
    if not self.CheckLoopListView.IsListViewInit then
        self.CheckLoopListView:InitListView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.CheckLoopListView, count)
    end
end

function PVPArenaMainPanelNode:OnGetItemByIndex(listView, idx)
    if idx < 0 then return end
    local index = idx + 1
    local matchChart = self:GetMatchChart()
    local data = matchChart[index]

    local cell = listView:NewListViewItem(PVPArenaBattleLiveCellName)
    local node = GetLuaBehaviour(cell.gameObject, PVPArenaBattleLiveCellPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        ---@type PVPArenaBattleLiveCell
        local mbEnv = node.Env
        mbEnv:RefreshUI(data)
    end
    return cell
end
