function PVPArenaMainPanelNode:RefreshCommonUI(mainPanelStatus)
    --- 是否是观众
    local isAudience   = self.isAudience
    local titleText, titleImgName, countdownTitleText, countdownTitleColor = self:InitCommonUIData(isAudience)

    self:RefreshTitle(titleText, titleImgName)
    self:RefreshTxtRankingNum()

    local isShowCountdown = mainPanelStatus ~= Constants.PVPArenaMainPanelStatus.Closed
    KTool.SetActive(self.Countdown.gameObject, isShowCountdown)
    if isShowCountdown then
        self:RegisterCountdownEvent()
        self:RefreshCountdownTitle(countdownTitleText, countdownTitleColor)
    else
        self:UnRegisterCountdownEvent()
    end
end

function PVPArenaMainPanelNode:RefreshTitle(titleText, titleImgName)
    self.TitleText.text = tostring(titleText)
    self.Title:LoadSprite(string.format("%s%s.png", BasePath, titleImgName))
end

function PVPArenaMainPanelNode:RefreshTxtRankingNum()
    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    --- 是否在比赛期
    local isBattle = seasonFlag >= PVPArenaSeasonFullStatus.Group
    --- 是否是玩家
    local isPlayer = not self.isAudience
    local isShowTxtRankingNum = isBattle or isPlayer
    KTool.SetActive(self.TxtRankingNum.gameObject, isShowTxtRankingNum)
    if not isShowTxtRankingNum then return end

    local roundOfNumber     = pvpArenaComponent:GetRoundOfNumber()
    --- 不在比赛期 并且 是玩家
    if not isBattle and isPlayer then
        self.TxtRankingNum.text = pvpArenaComponent:GetNumberOfContestants()
        self.Txtranking.text = localize("强")
    elseif pvpArenaComponent:GetRoundOfNumberIsNum() then
        self.TxtRankingNum.text = roundOfNumber
        self.Txtranking.text = localize("强")
    else
        self.TxtRankingNum.text = ""
        self.Txtranking.text = roundOfNumber
    end
end

function PVPArenaMainPanelNode:RefreshCountdownTitle(countdownTitleText, countdownTitleColor)
    self.TxtState.text  = countdownTitleText
    self.Imgtime:SetColor(countdownTitleColor)
    self.TxtState.color = countdownTitleColor
    self.TxtTime.color  = countdownTitleColor
end

function PVPArenaMainPanelNode:OnEventCountdownUpdate()
    local seconds = pvpArenaComponent:GetSeasonStageLeftSeconds()
    self.TxtTime.text = GetTimeHMS2(seconds)
end

